const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function writeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Браузер не разрешает сохранять выбор. Оставьте эту страницу открытой.')}}
let cart=readStore('sc-cart',{}),favorites=readStore('sc-favorites',[]),compare=readStore('sc-compare',[]);
function updateCounts(){$$('.cart-count').forEach(el=>el.textContent=Object.values(cart).reduce((sum,n)=>sum+Number(n),0))}
function toast(message){const el=$('.toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
updateCounts();
const menu=$('.menu-toggle');menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));menu.setAttribute('aria-label',expanded?'Открыть меню':'Закрыть меню');$('.mobile-nav').hidden=expanded});
const search=$('.search-dialog');$$('[data-open-search]').forEach(b=>b.addEventListener('click',()=>{search.showModal();$('#site-search').focus()}));$('[data-close-search]')?.addEventListener('click',()=>search.close());search?.addEventListener('click',event=>{if(event.target===search){const r=search.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)search.close()}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true')menu.click()});
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const price=value=>Number.isFinite(Number(value))&&value!==''?new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(value))+' ₽':'Цена по запросу';
const validQuantity=value=>Math.max(1,Math.min(9999,Math.floor(Number(value)||1)));
let catalogPromise;
async function getCatalog(){if(!catalogPromise)catalogPromise=fetch('/catalog.json').then(response=>{if(!response.ok)throw new Error('Catalog unavailable');return response.json()}).catch(error=>{catalogPromise=null;throw error});return catalogPromise}
function refreshSelectionButtons(){$$('[data-favorite]').forEach(button=>{const active=favorites.includes(button.dataset.favorite);button.setAttribute('aria-pressed',String(active));button.textContent=active?'♥':'♡'});$$('[data-compare]').forEach(button=>{const active=compare.includes(button.dataset.compare);button.setAttribute('aria-pressed',String(active));button.textContent=active?'Убрать из сравнения':'Добавить к сравнению'})}
function card(product){return `<article class="product-card" data-product="${product.id}"><div class="product-picture"><a href="${product.path}"><img src="${product.images[0]||'/assets/logo.png'}" alt="${escapeHTML(product.title)}" loading="lazy" width="350" height="350"></a><button class="favorite-button" data-favorite="${product.id}" aria-label="В избранное: ${escapeHTML(product.title)}" aria-pressed="${favorites.includes(product.id)}">${favorites.includes(product.id)?'♥':'♡'}</button></div><div class="product-card-info"><span class="product-category">${escapeHTML(product.category)}</span><a href="${product.path}"><h3>${escapeHTML(product.title)}</h3></a><div class="product-card-bottom"><span>${price(product.price)}</span><button class="add-small" data-add="${product.id}" aria-label="Добавить в корзину: ${escapeHTML(product.title)}">+</button></div></div></article>`}
document.addEventListener('click',event=>{
 const add=event.target.closest('[data-add]');if(add){const id=add.dataset.add;const amount=add.hasAttribute('data-detail-add')?validQuantity($('#product-quantity').value):1;cart[id]=validQuantity((cart[id]||0)+amount);writeStore('sc-cart',cart);updateCounts();toast(amount>1?`${amount} шт. добавлено в корзину`:'Изделие добавлено в корзину')}
 const favorite=event.target.closest('[data-favorite]');if(favorite){const id=favorite.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];writeStore('sc-favorites',favorites);refreshSelectionButtons();if($('[data-selection="favorites"]'))renderSelection()}
 const comparison=event.target.closest('[data-compare]');if(comparison){const id=comparison.dataset.compare;if(compare.includes(id))compare=compare.filter(x=>x!==id);else{if(compare.length>=4){toast('Можно сравнить до четырёх изделий');return}compare.push(id)}writeStore('sc-compare',compare);refreshSelectionButtons();toast(compare.includes(id)?'Добавлено к сравнению':'Убрано из сравнения')}
 const gallery=event.target.closest('[data-gallery]');if(gallery){$('#main-product-photo').src=gallery.dataset.gallery;$$('[data-gallery]').forEach(button=>{const active=button===gallery;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))})}
 const quantity=event.target.closest('[data-quantity]');if(quantity){const input=$('#product-quantity');input.value=validQuantity(Number(input.value)+Number(quantity.dataset.quantity))}
 const change=event.target.closest('[data-cart-change]');if(change){const id=change.dataset.id;cart[id]=validQuantity(Number(cart[id])+Number(change.dataset.cartChange));writeStore('sc-cart',cart);updateCounts();renderSelection()}
 const remove=event.target.closest('[data-remove]');if(remove){const id=remove.dataset.remove;if(remove.dataset.from==='compare'){compare=compare.filter(x=>x!==id);writeStore('sc-compare',compare)}else{delete cart[id];writeStore('sc-cart',cart);updateCounts()}renderSelection()}
 if(event.target.closest('[data-export-cart]'))exportCart();
 if(event.target.closest('[data-retry-selection]'))renderSelection();
});
$('#product-quantity')?.addEventListener('change',event=>{event.target.value=validQuantity(event.target.value)});
refreshSelectionButtons();

async function setupCatalog(){
 const root=$('[data-catalog]');if(!root)return;
 const form=$('#catalog-filters');const params=new URLSearchParams(location.search);form.elements.q.value=params.get('q')||'';form.elements.sort.value=['default','price-asc','price-desc','name'].includes(params.get('sort'))?params.get('sort'):'default';let page=Math.max(1,Number(params.get('page'))||1);let all;
 try{all=await getCatalog()}catch{$('#result-count').textContent='Показаны первые изделия. Поиск временно недоступен.';return}
 function render(reset=false){if(reset)page=1;const q=form.elements.q.value.trim().toLocaleLowerCase('ru');const sort=form.elements.sort.value;let items=all.filter(p=>(!root.dataset.catalog||p.categoryPath===root.dataset.catalog)&&(!q||`${p.title} ${p.category} ${p.description} ${p.id}`.toLocaleLowerCase('ru').includes(q)));
 if(sort==='price-asc')items.sort((a,b)=>(a.price===''?Infinity:Number(a.price))-(b.price===''?Infinity:Number(b.price)));if(sort==='price-desc')items.sort((a,b)=>(Number(b.price)||0)-(Number(a.price)||0));if(sort==='name')items.sort((a,b)=>a.title.localeCompare(b.title,'ru'));
 const pages=Math.ceil(items.length/24);page=Math.min(page,Math.max(pages,1));$('#result-count').textContent=`Найдено изделий: ${items.length}`;
 $('#product-grid').innerHTML=items.length?items.slice((page-1)*24,page*24).map(card).join(''):'<div class="empty-state"><span class="empty-symbol">✳</span><h2>Пока ничего не нашлось</h2><p>Попробуйте другое имя, название или символ.</p><button class="button outline" type="button" data-reset-filter>Сбросить поиск</button></div>';
 const numbers=[...new Set([1,...Array.from({length:5},(_,i)=>page-2+i).filter(x=>x>1&&x<pages),pages])].filter(x=>x>0);
 $('#catalog-pagination').innerHTML=pages>1?`<button data-page="${page-1}" ${page===1?'disabled':''} aria-label="Предыдущая страница">←</button>${numbers.map((n,i)=>`${i>0&&n>numbers[i-1]+1?'<span>…</span>':''}<button data-page="${n}" ${n===page?'aria-current="page"':''}>${n}</button>`).join('')}<button data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Следующая страница">→</button>`:'';
 const query=new URLSearchParams();if(q)query.set('q',form.elements.q.value.trim());if(sort!=='default')query.set('sort',sort);if(page>1)query.set('page',page);history.replaceState(null,'',location.pathname+(query.size?'?'+query.toString():''));refreshSelectionButtons();
 }
 form.addEventListener('submit',event=>{event.preventDefault();render(true)});form.elements.q.addEventListener('input',()=>render(true));form.elements.sort.addEventListener('change',()=>render(true));
 root.addEventListener('click',event=>{const pagination=event.target.closest('[data-page]');if(pagination){page=Number(pagination.dataset.page);render();form.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}if(event.target.closest('[data-reset-filter]')){form.elements.q.value='';render(true)}});render();
}
setupCatalog();

async function renderSelection(){
 const container=$('#selection-content');const page=$('[data-selection]')?.dataset.selection;if(!container)return;let products;
 try{products=await getCatalog()}catch{container.innerHTML='<div class="empty-state"><h2>Не удалось загрузить изделия</h2><p>Ваш выбор сохранён в этом браузере. Попробуйте ещё раз.</p><button class="button green" data-retry-selection>Повторить</button></div>';return}
 const items=products.filter(p=>page==='favorites'?favorites.includes(p.id):page==='compare'?compare.includes(p.id):Number(cart[p.id])>0);
 if(!items.length){container.innerHTML=`<div class="empty-state"><span class="empty-symbol">${page==='favorites'?'♡':'✳'}</span><h2>${page==='favorites'?'То, что вам понравится, будет здесь':page==='compare'?'Выберите изделия для сравнения':'Ваша коллекция начинается здесь'}</h2><p>${page==='favorites'?'Нажимайте на сердечко рядом с изделием.':page==='compare'?'Добавьте до четырёх изделий к сравнению из их карточек.':'Найдите свой символ в нашем каталоге.'}</p><a class="button green" href="/catalog/">Исследовать каталог ↗</a></div>`;return}
 if(page==='favorites'){container.innerHTML='<div class="product-grid">'+items.map(card).join('')+'</div>';return}
 if(page==='compare'){
 const keys=[...new Set(items.flatMap(p=>p.props.map(([key])=>key)))].filter(key=>key.trim());container.innerHTML='<div class="compare-scroll"><table class="compare-table"><thead><tr><th scope="col">Характеристики</th>'+items.map(p=>`<th scope="col"><a href="${p.path}"><img src="${p.images[0]}" alt="${escapeHTML(p.title)}"><span>${escapeHTML(p.title)}</span></a><button data-remove="${p.id}" data-from="compare" class="text-button">Убрать</button></th>`).join('')+'</tr></thead><tbody><tr><th scope="row">Цена</th>'+items.map(p=>`<td>${price(p.price)}</td>`).join('')+'</tr>'+keys.map(k=>`<tr><th scope="row">${escapeHTML(k)}</th>${items.map(p=>`<td>${escapeHTML(p.props.find(([key])=>key===k)?.[1]||'—')}</td>`).join('')}</tr>`).join('')+'</tbody></table></div>';return}
 const total=items.reduce((sum,p)=>sum+(Number(p.price)||0)*validQuantity(cart[p.id]),0);
 container.innerHTML='<div class="cart-layout"><div class="cart-items">'+items.map(p=>`<article class="cart-item"><a href="${p.path}" class="cart-item-image"><img src="${p.images[0]}" alt="${escapeHTML(p.title)}"></a><div class="cart-item-info"><a href="${p.path}"><h2>${escapeHTML(p.title)}</h2></a><p>${price(p.price)} / шт.</p><button class="text-button" data-remove="${p.id}">Удалить</button></div><div class="quantity"><button data-id="${p.id}" data-cart-change="-1" aria-label="Уменьшить количество ${escapeHTML(p.title)}">−</button><input type="number" data-cart-input="${p.id}" min="1" max="9999" value="${validQuantity(cart[p.id])}" aria-label="Количество: ${escapeHTML(p.title)}"><button data-id="${p.id}" data-cart-change="1" aria-label="Увеличить количество ${escapeHTML(p.title)}">+</button></div><strong>${price((Number(p.price)||0)*validQuantity(cart[p.id]))}</strong></article>`).join('')+`</div><aside class="cart-summary"><span class="eyebrow">ВАШ ВЫБОР</span><div class="cart-total"><span>Итого</span><strong>${price(total)}</strong></div><p>Розничные цены. Оптовые цены и стоимость доставки уточнит менеджер.</p><p class="minimum-note">${total<10000?'До минимального оптового заказа осталось '+price(10000-total)+'.':'Минимальная сумма оптового заказа достигнута.'}</p><a class="button green" id="email-order" href="#">Составить письмо с заказом ↗</a><button class="button outline" data-export-cart>Скачать список изделий ↓</button><p class="order-note">Откроется ваша почтовая программа с готовым списком. Проверьте письмо и отправьте его менеджеру. Заказ оформляется после подтверждения.</p><a class="text-link" href="https://silver-colubrid.ru/basket/" target="_blank" rel="noopener">Действующий интернет-магазин ↗</a><p class="order-note">Корзина действующего магазина заполняется отдельно.</p></aside></div>`;
 $('#email-order').href='mailto:silver_colubrid@mail.ru?subject='+encodeURIComponent('Заявка на сувенирные изделия')+'&body='+encodeURIComponent(orderText(items,total));
 $$('[data-cart-input]').forEach(input=>{
  input.addEventListener('input',()=>{
   if(input.value==='')return;
   const amount=validQuantity(input.value);input.value=amount;cart[input.dataset.cartInput]=amount;writeStore('sc-cart',cart);updateCounts();
   const product=items.find(p=>p.id===input.dataset.cartInput);input.closest('.cart-item').querySelector(':scope > strong').textContent=price((Number(product.price)||0)*amount);
   const total=items.reduce((sum,p)=>sum+(Number(p.price)||0)*validQuantity(cart[p.id]),0);$('.cart-total strong').textContent=price(total);$('.minimum-note').textContent=total<10000?'До минимального оптового заказа осталось '+price(10000-total)+'.':'Минимальная сумма оптового заказа достигнута.';
   $('#email-order').href='mailto:silver_colubrid@mail.ru?subject='+encodeURIComponent('Заявка на сувенирные изделия')+'&body='+encodeURIComponent(orderText(items,total));
  });
  input.addEventListener('change',()=>{cart[input.dataset.cartInput]=validQuantity(input.value);writeStore('sc-cart',cart);updateCounts();renderSelection()});
 });
}
function orderText(items,total){return 'Здравствуйте! Прошу рассчитать заказ:\n\n'+items.map(p=>`${p.title} (код ${p.id}) — ${validQuantity(cart[p.id])} шт. × ${price(p.price)}\nhttps://silver-colubrid.ru${p.path}`).join('\n\n')+'\n\nСумма по розничным ценам: '+price(total)+'\nПрошу уточнить оптовую стоимость, наличие и доставку.\n\nМоё имя:\nКонтактный телефон:\nГород доставки:'}
async function exportCart(){try{const all=await getCatalog();const items=all.filter(p=>cart[p.id]);const total=items.reduce((s,p)=>s+(Number(p.price)||0)*validQuantity(cart[p.id]),0);const blob=new Blob([orderText(items,total)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='Серебряный-полоз-заказ.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{toast('Не удалось подготовить список. Попробуйте ещё раз.')}}
renderSelection();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'search_silver_colubrid_products',title:'Найти изделия Серебряного полоза',description:'Поиск по локальному каталогу по названию, категории и описанию. Возвращает до 20 изделий с ценами и адресами страниц. Не меняет корзину и не отправляет заказ.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1,maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(!input||typeof input.query!=='string'||!input.query.trim()||input.query.length>200||Object.keys(input).some(key=>key!=='query'))throw new TypeError('Укажите непустой поисковый запрос длиной до 200 символов.');const query=input.query.trim().toLocaleLowerCase('ru');const products=await getCatalog();const found=products.filter(p=>`${p.title} ${p.category} ${p.description} ${p.id}`.toLocaleLowerCase('ru').includes(query));return{total:found.length,products:found.slice(0,20).map(p=>({id:p.id,title:p.title,price:p.price,currency:'RUB',path:p.path}))}}};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(error=>console.warn('Поиск для ассистентов недоступен в этом браузере.',error))}catch(error){console.warn('Поиск для ассистентов недоступен в этом браузере.',error)}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
